"""Experiment 010: train a small causal LM on text generated by its frozen copy.

The original model is retained as an immutable teacher. It samples a compact,
reusable sequence dataset; a student starts from the same weights and trains on
those sequences with next-token cross entropy plus teacher-logit distillation.
This is a quick feasibility experiment, not a claim that a tiny corpus preserves
all of a language model's knowledge.

Quick local run (after ``pipenv shell``)::

    python ./experiments/train_llm_exp010_self_distillation.py --local-files-only

Defaults use ``distilgpt2`` (about 82M parameters), 256 generated sequences, 48 new tokens,
and two epochs. Artifacts are written under ``experiments/output/train_llm``.
"""

from __future__ import annotations

import argparse
import copy
import json
import random
import sys
from pathlib import Path
from typing import Any

import torch
import torch.nn.functional as F
from torch.utils.data import DataLoader, TensorDataset

REPO_ROOT = Path(__file__).resolve().parents[1]
if str(REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(REPO_ROOT))

DEFAULT_MODEL = "distilgpt2"
DEFAULT_OUTPUT_DIR = Path(__file__).resolve().parent / "output" / "train_llm" / "exp010_self_distillation"
DEFAULT_DISTILLATION_WEIGHT = 0.8

TOPICS = (
    "a tiny neural network", "a quiet forest", "a robot learning music",
    "a helpful computer program", "a long train journey", "a curious scientist",
    "a new language model", "a changing weather pattern", "a time series forecast",
    "a picture and its caption", "a story about the ocean", "a useful invention",
)
PROMPT_TEMPLATES = (
    "Write a short explanation of {topic}, focusing on {angle}.",
    "Continue a story about {topic} with {angle}.",
    "In a few sentences, describe {topic} and include {angle}.",
    "What might happen next with {topic}? Consider {angle}.",
)
PROMPT_ANGLES = (
    "how it learns from examples", "what could go wrong", "a practical example",
    "how people might use it", "a surprising result", "a simple explanation",
    "a careful prediction", "a lesson from history", "how it changes over time",
    "what a beginner should know", "an unexpected connection", "a possible solution",
)


def make_prompts(count: int, seed: int) -> list[str]:
    """Make varied but reproducible natural-language prompts."""
    if count <= 0:
        raise ValueError("sequence count must be positive")
    rng = random.Random(seed)
    combinations = [
        template.format(topic=topic, angle=angle)
        for template in PROMPT_TEMPLATES
        for topic in TOPICS
        for angle in PROMPT_ANGLES
    ]
    rng.shuffle(combinations)
    prompts = combinations[:count]
    while len(prompts) < count:
        prompts.append(
            f"{rng.choice(combinations)} Additional detail {len(prompts)}:"
        )
    return prompts


def make_teacher_sequences(
    teacher: Any,
    tokenizer: Any,
    prompts: list[str],
    *,
    max_prompt_tokens: int,
    new_tokens: int,
    batch_size: int,
    device: torch.device,
    seed: int,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Generate padded teacher sequences and attention masks in small batches."""
    if max_prompt_tokens <= 0 or new_tokens <= 0 or batch_size <= 0:
        raise ValueError("prompt length, generated token count, and batch size must be positive")
    tokenizer.padding_side = "left"
    if tokenizer.pad_token_id is None:
        tokenizer.pad_token = tokenizer.eos_token
    pad_id = tokenizer.pad_token_id
    eos_id = tokenizer.eos_token_id
    ids_parts: list[torch.Tensor] = []
    masks: list[torch.Tensor] = []
    torch.manual_seed(seed)
    if device.type == "cuda":
        torch.cuda.manual_seed_all(seed)
    teacher.eval()
    for start in range(0, len(prompts), batch_size):
        batch_prompts = prompts[start : start + batch_size]
        encoded = tokenizer(
            batch_prompts,
            return_tensors="pt",
            padding="max_length",
            truncation=True,
            max_length=max_prompt_tokens,
        )
        input_ids = encoded["input_ids"].to(device)
        prompt_mask = encoded["attention_mask"].to(device)
        with torch.inference_mode():
            sequences = teacher.generate(
                input_ids=input_ids,
                attention_mask=prompt_mask,
                max_new_tokens=new_tokens,
                do_sample=True,
                temperature=0.9,
                top_k=40,
                top_p=0.92,
                pad_token_id=pad_id,
                eos_token_id=eos_id,
                use_cache=True,
            )
        generated_mask = torch.ones_like(sequences[:, input_ids.shape[1] :])
        # ``generate`` pads rows that reached EOS early with the same ID. Keep
        # the first EOS as a target and mask only the trailing padding after it.
        if eos_id is not None and generated_mask.numel():
            for row in range(generated_mask.shape[0]):
                eos_positions = (sequences[row, input_ids.shape[1] :] == eos_id).nonzero()
                if eos_positions.numel():
                    first_eos = int(eos_positions[0, 0])
                    generated_mask[row, first_eos + 1 :] = 0
        ids_parts.append(sequences.cpu())
        masks.append(torch.cat((prompt_mask, generated_mask), dim=1).cpu())
    return torch.cat(ids_parts), torch.cat(masks)


def distillation_loss(
    student_logits: torch.Tensor,
    teacher_logits: torch.Tensor,
    input_ids: torch.Tensor,
    attention_mask: torch.Tensor,
    *,
    temperature: float = 1.0,
    distillation_weight: float = DEFAULT_DISTILLATION_WEIGHT,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Causal next-token CE plus masked KL to the frozen teacher distribution."""
    if temperature <= 0:
        raise ValueError("temperature must be positive")
    if not 0.0 <= distillation_weight <= 1.0:
        raise ValueError("distillation_weight must be between zero and one")
    student = student_logits[:, :-1, :].float()
    teacher = teacher_logits[:, :-1, :].detach().float()
    targets = input_ids[:, 1:].clone()
    valid = attention_mask[:, 1:].bool()
    targets.masked_fill_(~valid, -100)
    cross_entropy = F.cross_entropy(
        student.reshape(-1, student.shape[-1]),
        targets.reshape(-1),
        ignore_index=-100,
    )
    teacher_log_probs = F.log_softmax(teacher / temperature, dim=-1)
    student_log_probs = F.log_softmax(student / temperature, dim=-1)
    token_kl = (
        teacher_log_probs.exp() * (teacher_log_probs - student_log_probs)
    ).sum(dim=-1)
    # Floating-point cancellation can produce tiny negative KL values when the
    # two distributions are identical; those values are numerical noise.
    token_kl = token_kl.clamp_min(0.0)
    mask = valid.to(token_kl.dtype)
    kl = (token_kl * mask).sum() / mask.sum().clamp_min(1.0)
    kl = kl * temperature**2
    loss = (1.0 - distillation_weight) * cross_entropy + distillation_weight * kl
    return loss, cross_entropy.detach(), kl.detach()


def evaluate_distillation(
    teacher: Any,
    student: Any,
    sequences: torch.Tensor,
    masks: torch.Tensor,
    *,
    batch_size: int,
    device: torch.device,
    distillation_weight: float = DEFAULT_DISTILLATION_WEIGHT,
) -> dict[str, float]:
    """Measure teacher agreement on a fixed set of teacher-generated sequences."""
    loader = DataLoader(TensorDataset(sequences, masks), batch_size=batch_size)
    teacher.eval()
    student.eval()
    totals = {"loss": 0.0, "cross_entropy": 0.0, "kl": 0.0, "tokens": 0}
    with torch.inference_mode():
        for input_ids, attention_mask in loader:
            input_ids = input_ids.to(device)
            attention_mask = attention_mask.to(device)
            teacher_logits = teacher(input_ids=input_ids, attention_mask=attention_mask).logits
            student_logits = student(input_ids=input_ids, attention_mask=attention_mask).logits
            loss, ce, kl = distillation_loss(
                student_logits,
                teacher_logits,
                input_ids,
                attention_mask,
                distillation_weight=distillation_weight,
            )
            token_count = int(attention_mask[:, 1:].sum().item())
            totals["loss"] += float(loss) * token_count
            totals["cross_entropy"] += float(ce) * token_count
            totals["kl"] += float(kl) * token_count
            totals["tokens"] += token_count
    denominator = max(int(totals["tokens"]), 1)
    return {
        key: float(totals[key]) / denominator
        for key in ("loss", "cross_entropy", "kl")
    }


def greedy_continuations(
    model: Any,
    tokenizer: Any,
    prompts: list[str],
    *,
    max_prompt_tokens: int,
    new_tokens: int,
    device: torch.device,
) -> tuple[list[list[int]], list[str]]:
    """Generate deterministic continuations for a small fixed prompt set."""
    tokenizer.padding_side = "left"
    if tokenizer.pad_token_id is None:
        tokenizer.pad_token = tokenizer.eos_token
    encoded = tokenizer(
        prompts,
        return_tensors="pt",
        padding="max_length",
        truncation=True,
        max_length=max_prompt_tokens,
    )
    input_ids = encoded["input_ids"].to(device)
    attention_mask = encoded["attention_mask"].to(device)
    model.eval()
    with torch.inference_mode():
        generated = model.generate(
            input_ids=input_ids,
            attention_mask=attention_mask,
            max_new_tokens=new_tokens,
            do_sample=False,
            pad_token_id=tokenizer.pad_token_id,
            eos_token_id=tokenizer.eos_token_id,
            use_cache=True,
        )
    tails = generated[:, input_ids.shape[1] :].cpu().tolist()
    texts = [tokenizer.decode(tokens, skip_special_tokens=True) for tokens in tails]
    return tails, texts


def train_student(
    teacher: Any,
    student: Any,
    sequences: torch.Tensor,
    masks: torch.Tensor,
    *,
    epochs: int,
    batch_size: int,
    learning_rate: float,
    device: torch.device,
    seed: int,
    distillation_weight: float = DEFAULT_DISTILLATION_WEIGHT,
) -> list[dict[str, float]]:
    """Train the copy on frozen-teacher sequences and soft next-token targets.

    This loop stays experiment-local because the project's shared
    ``gradient_descent`` currently assumes float image inputs, class labels,
    and ``max(dim=1)`` accuracy. Causal-LM training needs integer token IDs,
    shifted token targets, padding masks, and teacher KL metrics.
    """
    if epochs <= 0 or batch_size <= 0 or learning_rate <= 0:
        raise ValueError("epochs, batch size, and learning rate must be positive")
    generator = torch.Generator().manual_seed(seed)
    loader = DataLoader(
        TensorDataset(sequences, masks),
        batch_size=batch_size,
        shuffle=True,
        generator=generator,
    )
    optimizer = torch.optim.AdamW(student.parameters(), lr=learning_rate)
    history: list[dict[str, float]] = []
    student.train()
    teacher.eval()
    for epoch in range(epochs):
        sums = {"loss": 0.0, "cross_entropy": 0.0, "kl": 0.0, "tokens": 0}
        for input_ids, attention_mask in loader:
            input_ids = input_ids.to(device)
            attention_mask = attention_mask.to(device)
            with torch.no_grad():
                teacher_logits = teacher(
                    input_ids=input_ids, attention_mask=attention_mask
                ).logits
            student_logits = student(
                input_ids=input_ids, attention_mask=attention_mask
            ).logits
            loss, ce, kl = distillation_loss(
                student_logits,
                teacher_logits,
                input_ids,
                attention_mask,
                distillation_weight=distillation_weight,
            )
            optimizer.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(student.parameters(), max_norm=1.0)
            optimizer.step()
            token_count = int(attention_mask[:, 1:].sum().item())
            sums["loss"] += float(loss.detach()) * token_count
            sums["cross_entropy"] += float(ce) * token_count
            sums["kl"] += float(kl) * token_count
            sums["tokens"] += token_count
        denominator = max(int(sums["tokens"]), 1)
        metrics = {
            key: float(sums[key]) / denominator
            for key in ("loss", "cross_entropy", "kl")
        }
        metrics["epoch"] = float(epoch + 1)
        history.append(metrics)
        print(
            f"epoch={epoch + 1}/{epochs} loss={metrics['loss']:.5f} "
            f"ce={metrics['cross_entropy']:.5f} kl={metrics['kl']:.6f}",
            flush=True,
        )
    return history


def _parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--model", default=DEFAULT_MODEL)
    parser.add_argument("--output-dir", type=Path, default=DEFAULT_OUTPUT_DIR)
    parser.add_argument("--sequences", type=int, default=256)
    parser.add_argument("--max-prompt-tokens", type=int, default=12)
    parser.add_argument("--new-tokens", type=int, default=48)
    parser.add_argument("--epochs", type=int, default=2)
    parser.add_argument("--batch-size", type=int, default=8)
    parser.add_argument("--learning-rate", type=float, default=3e-5)
    parser.add_argument(
        "--distillation-weight", type=float, default=DEFAULT_DISTILLATION_WEIGHT,
        help="weight on teacher KL loss; the remaining weight goes to generated-token CE",
    )
    parser.add_argument("--seed", type=int, default=10)
    parser.add_argument("--device", default="auto", choices=("auto", "cpu", "cuda"))
    parser.add_argument("--local-files-only", action="store_true")
    return parser.parse_args()


def main() -> None:
    args = _parse_args()
    try:
        from transformers import AutoModelForCausalLM, AutoTokenizer
    except ImportError as exc:
        raise SystemExit(
            "Experiment 010 requires Transformers. Install it in the active Pipenv environment."
        ) from exc
    if args.device == "cuda" and not torch.cuda.is_available():
        raise SystemExit("CUDA was requested but is not available")
    if not 0.0 <= args.distillation_weight <= 1.0:
        raise SystemExit("--distillation-weight must be between zero and one")
    if args.sequences < 2:
        raise SystemExit("--sequences must be at least two for train/validation splitting")
    device = torch.device(
        "cuda" if args.device == "auto" and torch.cuda.is_available()
        else "cpu" if args.device == "auto" else args.device
    )
    random.seed(args.seed)
    torch.manual_seed(args.seed)
    if device.type == "cuda":
        torch.cuda.manual_seed_all(args.seed)
    args.output_dir.mkdir(parents=True, exist_ok=True)

    print(f"Loading frozen teacher and student source: {args.model} on {device}", flush=True)
    load_options = {"local_files_only": args.local_files_only}
    tokenizer = AutoTokenizer.from_pretrained(args.model, **load_options)
    teacher = AutoModelForCausalLM.from_pretrained(args.model, **load_options).to(device).eval()
    teacher.requires_grad_(False)
    student = copy.deepcopy(teacher).to(device).train()
    student.requires_grad_(True)
    parameter_count = sum(parameter.numel() for parameter in teacher.parameters())
    print(f"Parameters per model: {parameter_count:,}", flush=True)

    torch.save(
        {key: value.detach().cpu() for key, value in teacher.state_dict().items()},
        args.output_dir / "teacher_original_state.pt",
    )
    torch.save(
        {key: value.detach().cpu() for key, value in student.state_dict().items()},
        args.output_dir / "student_initial_state.pt",
    )

    prompts = make_prompts(args.sequences, args.seed)
    sequences, attention_masks = make_teacher_sequences(
        teacher,
        tokenizer,
        prompts,
        max_prompt_tokens=args.max_prompt_tokens,
        new_tokens=args.new_tokens,
        batch_size=args.batch_size,
        device=device,
        seed=args.seed,
    )
    torch.save(
        {"input_ids": sequences, "attention_mask": attention_masks, "prompts": prompts},
        args.output_dir / "teacher_generated_dataset.pt",
    )
    decoded_examples = [
        tokenizer.decode(row[mask.bool()].tolist(), skip_special_tokens=True)
        for row, mask in zip(sequences[:5], attention_masks[:5])
    ]
    print(
        f"Teacher dataset: {len(sequences)} sequences, {int(attention_masks.sum())} valid tokens, "
        f"shape={tuple(sequences.shape)}",
        flush=True,
    )
    for index, example in enumerate(decoded_examples, start=1):
        print(f"  sample_{index}: {ascii(example)}", flush=True)

    split = max(1, min(len(sequences) - 1, int(len(sequences) * 0.85)))
    train_sequences, validation_sequences = sequences[:split], sequences[split:]
    train_masks, validation_masks = attention_masks[:split], attention_masks[split:]
    before = evaluate_distillation(
        teacher, student, validation_sequences, validation_masks,
        batch_size=args.batch_size, device=device,
        distillation_weight=args.distillation_weight,
    )
    history = train_student(
        teacher,
        student,
        train_sequences,
        train_masks,
        epochs=args.epochs,
        batch_size=args.batch_size,
        learning_rate=args.learning_rate,
        device=device,
        seed=args.seed,
        distillation_weight=args.distillation_weight,
    )
    after = evaluate_distillation(
        teacher, student, validation_sequences, validation_masks,
        batch_size=args.batch_size, device=device,
        distillation_weight=args.distillation_weight,
    )
    generation_prompts = make_prompts(min(6, args.sequences), args.seed + 1)
    teacher_tokens, teacher_texts = greedy_continuations(
        teacher,
        tokenizer,
        generation_prompts,
        max_prompt_tokens=args.max_prompt_tokens,
        new_tokens=args.new_tokens,
        device=device,
    )
    student_tokens, student_texts = greedy_continuations(
        student,
        tokenizer,
        generation_prompts,
        max_prompt_tokens=args.max_prompt_tokens,
        new_tokens=args.new_tokens,
        device=device,
    )
    compared_tokens = sum(len(tokens) for tokens in teacher_tokens)
    matching_tokens = sum(
        left == right
        for teacher_row, student_row in zip(teacher_tokens, student_tokens)
        for left, right in zip(teacher_row, student_row)
    )
    generation_comparison = {
        "prompts": generation_prompts,
        "teacher_continuations": teacher_texts,
        "student_continuations": student_texts,
        "greedy_token_match_fraction": (
            matching_tokens / compared_tokens if compared_tokens else 1.0
        ),
        "compared_token_count": compared_tokens,
    }
    torch.save(
        {key: value.detach().cpu() for key, value in student.state_dict().items()},
        args.output_dir / "student_trained_state.pt",
    )
    report = {
        "experiment": "010_self_distillation",
        "model": args.model,
        "device": str(device),
        "seed": args.seed,
        "parameters_per_model": parameter_count,
        "sequence_count": len(sequences),
        "train_sequences": len(train_sequences),
        "validation_sequences": len(validation_sequences),
        "sequence_length": int(sequences.shape[1]),
        "valid_tokens": int(attention_masks.sum()),
        "epochs": args.epochs,
        "batch_size": args.batch_size,
        "learning_rate": args.learning_rate,
        "distillation_weight": args.distillation_weight,
        "validation_before": before,
        "training_history": history,
        "validation_after": after,
        "generation_comparison": generation_comparison,
        "dataset_text_examples": decoded_examples,
    }
    report_path = args.output_dir / "report.json"
    report_path.write_text(json.dumps(report, indent=2), encoding="utf-8")
    print(f"Validation before: {before}", flush=True)
    print(f"Validation after:  {after}", flush=True)
    print(
        "Greedy continuation token match: "
        f"{generation_comparison['greedy_token_match_fraction']:.3f} "
        f"({matching_tokens}/{compared_tokens})",
        flush=True,
    )
    for prompt, teacher_text, student_text in zip(
        generation_prompts[:3], teacher_texts[:3], student_texts[:3]
    ):
        print(f"  prompt={ascii(prompt)}", flush=True)
        print(f"    teacher={ascii(teacher_text)}", flush=True)
        print(f"    student={ascii(student_text)}", flush=True)
    print(f"Artifacts: {args.output_dir}", flush=True)
    print(f"Report: {report_path}", flush=True)


if __name__ == "__main__":
    main()
